@Article{AAMM-12-1, author = {Xiuli, Wang and Zhai, Qilong and Zhang, Ran and Zhang, Shangyou}, title = {The Weak Galerkin Finite Element Method for Solving the Time-Dependent Integro-Differential Equations}, journal = {Advances in Applied Mathematics and Mechanics}, year = {2020}, volume = {12}, number = {1}, pages = {164--188}, abstract = {

In this paper, we solve linear parabolic integral differential equations using the weak Galerkin finite element method (WG) by adding a stabilizer. The semi-discrete and fully-discrete weak Galerkin finite element schemes are constructed. Optimal convergent orders of the solution of the WG in $L^2$ and $H^1$ norm are derived. Several computational results confirm the correctness and efficiency of the method.

}, issn = {2075-1354}, doi = {https://doi.org/10.4208/aamm.OA-2019-0088}, url = {https://global-sci.com/article/73030/the-weak-galerkin-finite-element-method-for-solving-the-time-dependent-integro-differential-equations} }
